<template>
	<view class="notice-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="back-btn" @click="goBack">‹</view>
				<text class="nav-title">{{ pageTitle }}</text>
				<view class="read-btn" :class="{ hidden: !unreadCount }" @click="markAllRead">全部已读</view>
			</view>
		</view>

		<scroll-view class="notice-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerHeight + 'px' }">
			<view class="notice-list">
				<view class="notice-tabs">
					<view class="notice-tab" :class="{ active: activeTab === 'interaction' }" @click="switchNoticeTab('interaction')">
						<text>互动通知</text>
						<text v-if="interactionUnreadCount" class="tab-badge">{{ formatBadge(interactionUnreadCount) }}</text>
					</view>
					<view class="notice-tab" :class="{ active: activeTab === 'system' }" @click="switchNoticeTab('system')">
						<text>系统通知</text>
						<text v-if="systemUnreadCount" class="tab-badge">{{ formatBadge(systemUnreadCount) }}</text>
					</view>
				</view>

				<view v-if="loading" class="empty-state">正在整理通知...</view>
				<view v-else-if="!displayNotices.length" class="empty-state">
					<text class="empty-title">{{ emptyTitle }}</text>
					<text class="empty-copy">新的互动与提醒会及时出现在这里</text>
				</view>
				<view v-else class="notice-items">
					<view v-for="item in displayNotices" :key="item.id" class="notice-card" :class="[{ unread: !item.read }, `type-${item.type}`]" @click="openNotice(item)">
						<view class="notice-leading">
							<image v-if="item.type === 'system'" class="icon notice-icon" src="/static/notice.png" mode="aspectFit" />
							<image
								v-else-if="item.actor && item.actor.avatar"
								class="actor-avatar"
								:src="item.actor.avatar"
								mode="aspectFill"
								@click.stop="openActorProfile(item)"
							/>
							<view v-else class="icon">{{ item.icon }}</view>
							<text v-if="!item.read" class="unread-badge">新</text>
						</view>
						<view class="notice-main">
							<view class="notice-head">
								<text class="title">{{ item.title }}</text>
								<text class="time">{{ item.time }}</text>
							</view>
							<text class="content">{{ item.content }}</text>
							<view class="notice-foot">
								<text class="type-label">{{ getTypeLabel(item.type) }}</text>
								<text v-if="item.sourceId" class="detail-link">查看详情 ›</text>
							</view>
						</view>
					</view>
				</view>
			</view>
		</scroll-view>
	</view>
</template>

<script>
import { fetchNotifications, markNotificationRead, markNotificationsReadAll } from '../../api/notification';
import { showRequestError } from '../../utils/feedback';
import * as profileGuard from '../../utils/profileGuard';

export default {
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 96,
			type: '',
			loading: false,
			notices: [],
			summary: {
				commentCount: 0,
				resonanceCount: 0,
				followCount: 0,
				noteCount: 0,
				systemCount: 0,
				totalUnread: 0
			}
		};
	},
	computed: {
		pageTitle() {
			const titles = {
				comment: '评论通知',
				resonance: '共鸣通知',
				follow: '关注通知',
				note: '纸条通知'
			};
			return titles[this.type] || '通知';
		},
		activeTab() {
			return this.type === 'system' ? 'system' : 'interaction';
		},
		displayNotices() {
			return this.type ? this.notices : this.notices.filter((item) => item.type !== 'system');
		},
		unreadCount() {
			const keys = {
				comment: 'commentCount',
				resonance: 'resonanceCount',
				follow: 'followCount',
				note: 'noteCount',
				system: 'systemCount'
			};
			if (!this.type) return this.interactionUnreadCount;
			return Number(this.summary[keys[this.type]] || 0);
		},
		systemUnreadCount() {
			return Number(this.summary.systemCount || 0);
		},
		interactionUnreadCount() {
			return Math.max(0, Number(this.summary.totalUnread || 0) - this.systemUnreadCount);
		},
		emptyTitle() {
			if (this.type === 'system') return '暂时没有系统通知';
			return this.type ? `暂时没有${this.pageTitle}` : '暂时没有新的互动通知';
		}
	},
	onLoad(query = {}) {
		this.type = this.normalizeType(query.type || '');
		this.setHeaderHeight();
	},
	onShow() {
		this.loadNotifications();
	},
	methods: {
		normalizeType(type = '') {
			const map = {
				comment: 'comment',
				like: 'resonance',
				friend: 'follow',
				note: 'note',
				system: 'system'
			};
			return map[type] || type;
		},
		getIcon(type = '') {
			const map = {
				comment: '评',
				resonance: '鸣',
				follow: '关',
				note: '纸',
				system: '告'
			};
			return map[type] || '知';
		},
		getTypeLabel(type = '') {
			const map = {
				comment: '评论',
				resonance: '共鸣',
				follow: '关注',
				note: '纸条',
				system: '系统'
			};
			return map[type] || '通知';
		},
		normalizeNotice(item = {}) {
			const actor = item.actor && item.actor.id ? item.actor : null;
			const actorName = actor
				? String(actor.nickname || actor.stampNo || '').trim()
				: '';
			const rawContent = String(item.content || '');
			return {
				id: item.id || '',
				type: item.type || '',
				icon: this.getIcon(item.type),
				title: actorName || item.title || '通知',
				content: actorName && rawContent.startsWith(actorName)
					? rawContent.slice(actorName.length)
					: rawContent,
				time: item.time || '',
				read: Boolean(item.read),
				sourceType: item.sourceType || '',
				sourceId: item.sourceId || '',
				actor: actor ? {
					id: actor.id,
					name: actor.nickname || actor.stampNo || '',
					avatar: actor.avatarUrl || ''
				} : null
			};
		},
		applySummary(value = {}) {
			const summary = value && value.summary ? value.summary : value;
			this.summary = {
				commentCount: Number(summary.commentCount || 0),
				resonanceCount: Number(summary.resonanceCount || 0),
				followCount: Number(summary.followCount || 0),
				noteCount: Number(summary.noteCount || 0),
				systemCount: Number(summary.systemCount || 0),
				totalUnread: Number(summary.totalUnread || 0)
			};
		},
		async loadNotifications() {
			this.loading = true;
			try {
				const result = await fetchNotifications({
					type: this.type,
					limit: 100
				});
				const items = Array.isArray(result && result.items) ? result.items : [];
				this.notices = items.map(this.normalizeNotice);
				this.applySummary(result && result.summary ? result.summary : {});
			} catch (error) {
				showRequestError(error, '通知加载失败');
			} finally {
				this.loading = false;
			}
		},
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				this.statusBarHeight = info.statusBarHeight || 44;
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.headerHeight = this.statusBarHeight + Math.round(96 * rpxToPx);
			} catch (error) {
				this.headerHeight = 96;
			}
		},
		showToast(title) {
			uni.showToast({ title, icon: 'none' });
		},
		async markAllRead() {
			if (!this.unreadCount) return;
			try {
				const types = this.type
					? [this.type]
					: ['comment', 'resonance', 'follow', 'note'];
				let result = null;
				for (const type of types) {
					result = await markNotificationsReadAll(type);
				}
				this.notices = this.notices.map((item) => (
					this.type || item.type !== 'system' ? { ...item, read: true } : item
				));
				if (result) this.applySummary(result);
				this.showToast('已全部标记为已读');
			} catch (error) {
				showRequestError(error, '标记已读失败');
			}
		},
		decreaseUnread(type = '') {
			const keys = {
				comment: 'commentCount',
				resonance: 'resonanceCount',
				follow: 'followCount',
				note: 'noteCount',
				system: 'systemCount'
			};
			const key = keys[type];
			if (!key) return;
			this.summary = {
				...this.summary,
				[key]: Math.max(0, Number(this.summary[key] || 0) - 1),
				totalUnread: Math.max(0, Number(this.summary.totalUnread || 0) - 1)
			};
		},
		readNotice(item) {
			const current = this.notices.find((notice) => notice.id === item.id);
			if (current && !current.read) {
				this.notices = this.notices.map((notice) => (
					notice.id === item.id ? { ...notice, read: true } : notice
				));
				this.decreaseUnread(item.type);
				markNotificationRead(item.id)
					.then((summary) => this.applySummary(summary))
					.catch(() => this.loadNotifications());
			}
		},
		async openActorProfile(item) {
			const actorId = item && item.actor ? item.actor.id : '';
			if (!actorId) return;
			this.readNotice(item);
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看主页' }))) return;
			uni.navigateTo({ url: `/pages/user/index?id=${encodeURIComponent(actorId)}` });
		},
		async openNotice(item) {
			this.readNotice(item);

			if (item.sourceType === 'capsule' && item.sourceId) {
				if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看详情' }))) return;
				uni.navigateTo({ url: `/pages/detail/index?id=${item.sourceId}` });
				return;
			}

			if (item.sourceType === 'user' && item.sourceId) {
				if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看主页' }))) return;
				uni.navigateTo({ url: `/pages/user/index?id=${item.sourceId}` });
				return;
			}

			if (item.sourceType === 'note' && item.sourceId) {
				uni.navigateTo({ url: `/pages/drift/mailbox?noteId=${encodeURIComponent(item.sourceId)}` });
			}
		},
		switchNoticeTab(tab) {
			const nextType = tab === 'system' ? 'system' : '';
			if (this.type === nextType || this.loading) return;
			this.type = nextType;
			this.notices = [];
			this.loadNotifications();
		},
		formatBadge(value) {
			const count = Number(value || 0);
			return count > 99 ? '99+' : String(count);
		},
		goBack() {
			uni.navigateBack();
		}
	}
};
</script>

<style lang="scss" scoped>
.notice-page {
	min-height: 100vh;
	background: #f7f3f6;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 10;
	background: rgba(255, 255, 255, 0.97);
	border-bottom: 1rpx solid #f0e5ea;
}

.nav-bar {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 96rpx;
	padding: 0 28rpx;
}

.back-btn,
.read-btn {
	display: flex;
	align-items: center;
	justify-content: flex-end;
	min-width: 110rpx;
	height: 72rpx;
	color: #d4688a;
	font-size: 22rpx;
	font-weight: 600;
}

.read-btn.hidden {
	visibility: hidden;
}

.back-btn {
	justify-content: flex-start;
	min-width: 110rpx;
	font-size: 52rpx;
	color: #33262e;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	text-align: center;
	font-size: 32rpx;
	font-weight: 700;
	color: #221820;
}

.notice-scroll {
	height: 100vh;
}

.notice-list {
	padding: 24rpx 24rpx 64rpx;
}

.notice-tabs {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: 6rpx;
	height: 76rpx;
	margin-bottom: 16rpx;
	padding: 6rpx;
	box-sizing: border-box;
	border-radius: 16rpx;
	background: #ebe7eb;
}

.notice-tab {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 10rpx;
	min-width: 0;
	border-radius: 12rpx;
	color: #887d86;
	font-size: 24rpx;
	font-weight: 600;
}

.notice-tab.active {
	background: #ffffff;
	color: #302630;
	box-shadow: 0 4rpx 14rpx rgba(70, 53, 66, 0.08);
}

.notice-tab.active::after {
	content: '';
	position: absolute;
	left: 50%;
	bottom: 4rpx;
	width: 30rpx;
	height: 4rpx;
	border-radius: 999rpx;
	background: #d4688a;
	transform: translateX(-50%);
}

.tab-badge {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-width: 32rpx;
	height: 32rpx;
	padding: 0 8rpx;
	box-sizing: border-box;
	border-radius: 999rpx;
	background: #d4688a;
	color: #ffffff;
	font-size: 17rpx;
	font-weight: 700;
}

.empty-state {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	min-height: 300rpx;
	padding: 0 30rpx;
	box-sizing: border-box;
	color: #9c8c95;
	font-size: 23rpx;
	text-align: center;
}

.empty-title {
	color: #625660;
	font-size: 27rpx;
	font-weight: 600;
}

.empty-copy {
	margin-top: 12rpx;
	color: #aaa0a8;
	font-size: 21rpx;
	line-height: 1.5;
}

.notice-card {
	position: relative;
	display: flex;
	gap: 18rpx;
	padding: 22rpx;
	border: 1rpx solid transparent;
	border-radius: 16rpx;
	background: #ffffff;
	box-shadow: 0 8rpx 24rpx rgba(71, 55, 68, 0.05);
}

.notice-card.unread {
	border-color: rgba(212, 104, 138, 0.2);
	background: #fffafd;
}

.notice-card + .notice-card {
	margin-top: 16rpx;
}

.notice-leading {
	position: relative;
	width: 72rpx;
	height: 72rpx;
	flex-shrink: 0;
}

.icon,
.actor-avatar {
	width: 72rpx;
	height: 72rpx;
	border-radius: 16rpx;
}

.notice-icon {
	display: block;
	background: transparent;
}

.actor-avatar {
	display: block;
	box-sizing: border-box;
	border: 3rpx solid #ffffff;
	background: #f0ebef;
	box-shadow: 0 5rpx 14rpx rgba(77, 58, 72, 0.1);
}

.icon {
	display: flex;
	align-items: center;
	justify-content: center;
	background: #5b5661;
	color: #ffffff;
	font-size: 24rpx;
	font-weight: 800;
}

.type-comment .icon { background: #df718d; }
.type-resonance .icon { background: #7083bd; }
.type-follow .icon { background: #55998f; }
.type-note .icon { background: #b78656; }
.type-system .icon { background: #5b5661; }
.type-system .notice-icon { background: transparent; }

.unread-badge {
	position: absolute;
	top: -9rpx;
	right: -9rpx;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 34rpx;
	height: 34rpx;
	box-sizing: border-box;
	border: 3rpx solid #ffffff;
	border-radius: 50%;
	background: #ed668f;
	color: #ffffff;
	font-size: 16rpx;
	font-weight: 700;
	box-shadow: 0 5rpx 12rpx rgba(212, 104, 138, 0.24);
}

.notice-main {
	flex: 1;
	min-width: 0;
}

.notice-head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 16rpx;
}

.title {
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	font-size: 27rpx;
	font-weight: 700;
	color: #241b22;
}

.time {
	flex-shrink: 0;
	font-size: 22rpx;
	color: #b9aab2;
}

.content {
	display: block;
	margin-top: 9rpx;
	font-size: 23rpx;
	line-height: 1.5;
	color: #7d7078;
}

.notice-foot {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 16rpx;
	margin-top: 13rpx;
}

.type-label {
	display: inline-flex;
	align-items: center;
	height: 30rpx;
	padding: 0 11rpx;
	border-radius: 999rpx;
	background: #f3eff2;
	color: #8b7e87;
	font-size: 18rpx;
}

.detail-link {
	color: #c36c8b;
	font-size: 19rpx;
}
</style>
